### 3. **Add Unit Test with Header Validation**

Write a test to verify that the `x-amz-server-side-encryption` header is present and set to `aws:kms`.

#### ✅ Example: Jest Test
```ts
describe('UserProfileStorageService', () => {
  let service: UserProfileStorageService;
  let mockS3Client: any;

  beforeEach(() => {
    mockS3Client = {
      send: jest.fn(),
    };
    service = new UserProfileStorageService();
    // Replace real client with mock
    (service as any).s3Client = mockS3Client;
  });

  it('should include SSE-KMS headers when uploading', async () => {
    const mockResponse = { ETag: 'abc123' };
    mockS3Client.send.mockResolvedValueOnce(mockResponse);

    await service.uploadProfile('user123', Buffer.from(JSON.stringify({ name: 'John' })));

    const call = mockS3Client.send.mock.calls[0][0];
    expect(call.input.ServerSideEncryption).toBe('aws:kms');
    expect(call.input.SSEKMSKeyId).toBe('alias/user-profile-data-encryption');
    expect(call.input.ContentType).toBe('application/json');
  });

  it('should reject upload if missing encryption headers', async () => {
    mockS3Client.send.mockRejectedValueOnce(new Error('Missing encryption header'));

    await expect(service.uploadProfile('user123', Buffer.from('{}'))).rejects.toThrow();
  });
});
```

